public interface ISeatPricingStrategy
{
    decimal CalculatePrice(Seat seat, Show show);
}

public class PremiumSeatPricing : ISeatPricingStrategy
{
    private readonly HashSet<string> _premiumRows = new() { "A", "B", "C" };
    private readonly decimal _premiumMultiplier = 1.5m;

    public decimal CalculatePrice(Seat seat, Show show)
    {
        decimal basePrice = seat.Price;
        if (_premiumRows.Contains(seat.Row))
            basePrice *= _premiumMultiplier;
        // Surge pricing based on how full the show is
        var occupancy = show.GetOccupancyRate();
        if (occupancy > 0.8m)
            basePrice *= 1.2m;
        return Math.Round(basePrice, 2);
    }
}

public class ShowtimeSearch
{
    private readonly List<Show> _allShows = new();

    public IEnumerable<Show> Search(string? movieTitle, DateOnly? date, int? screenNumber)
    {
        return _allShows.Where(s =>
            (movieTitle == null || s.MovieTitle.Contains(movieTitle, StringComparison.OrdinalIgnoreCase)) &&
            (!date.HasValue || DateOnly.FromDateTime(s.StartTime) == date.Value) &&
            (!screenNumber.HasValue || s.ScreenNumber == screenNumber.Value));
    }
}
